STAGES = [('locate', 'stages/01_locate.py', '# locate: find the rod with own vision (mask + depth of the two global cameras, cylinder fit);\n# the tracker is only printed for comparison (r01: it goes stale / wrong when the hand occludes the rod).\nfrom assembly_policy.sim.robot import quat_to_mat, mat_to_quat, quat_mul, quat_conj, axis_angle_quat\nnp.set_printoptions(precision=4, suppress=True)\n\n_M = api.part_model()\nPB0 = np.asarray(_M["bbox_min"], float)\nPB1 = np.asarray(_M["bbox_max"], float)\n_ext = PB1 - PB0\nAX = int(np.argmax(_ext))                      # long axis of the rod in the part frame\n_mid = (PB0 + PB1) / 2\nE0 = _mid.copy(); E0[AX] = PB0[AX]             # the two axis end points in the part frame\nE1 = _mid.copy(); E1[AX] = PB1[AX]\nL = float(_ext[AX])\nRAD = float(np.delete(_ext, AX).max() / 2)\nEZ = np.array([0.0, 0.0, 1.0])\n\n\ndef Tm(p, R):\n    M = np.eye(4); M[:3, :3] = R; M[:3, 3] = p\n    return M\n\n\ndef Tinv(M):\n    R = M[:3, :3]; p = M[:3, 3]\n    return Tm(-R.T @ p, R.T)\n\n\ndef rotz(a):\n    c, s = np.cos(a), np.sin(a)\n    return np.array([[c, -s, 0], [s, c, 0], [0, 0, 1.0]])\n\n\ndef unit(v):\n    v = np.asarray(v, float)\n    return v / max(np.linalg.norm(v), 1e-12)\n\n\ndef tcp_T():\n    o = api.observe()\n    return Tm(np.asarray(o["tcp_pos"], float), quat_to_mat(np.asarray(o["tcp_quat"], float)))\n\n\ndef tracker():\n    p, q, c = api.locate_part()\n    if p is None:\n        return None\n    p = np.asarray(p, float); R = quat_to_mat(np.asarray(q, float))\n    return p + R @ E0, p + R @ E1, c\n\n\ndef backproject(c, sel):\n    vs, us = np.nonzero(sel)\n    d = c["depth"][vs, us]\n    K = np.asarray(c["K"], float)\n    P = np.stack([(us + .5 - K[0, 2]) / K[0, 0] * d, -(vs + .5 - K[1, 2]) / K[1, 1] * d, -d], 1)\n    return np.asarray(c["cam_pos"], float) + P @ np.asarray(c["cam_R"], float).T\n\n\ndef fit_rod(names=("global", "global2"), cams=None):\n    """Cylinder fit (known radius) to the part-mask depth points. Returns dict with axis dir a,\n    axis point, visible end points p0/p1 (along a), extent, rms, n."""\n    cams = cams if cams is not None else api.camera()\n    P, C = [], []\n    for n in names:\n        c = cams[n]\n        m = np.asarray(c["mask"], bool)\n        # drop mask boundary pixels (depth may belong to the background)\n        inner = m.copy()\n        inner[1:, :] &= m[:-1, :]; inner[:-1, :] &= m[1:, :]\n        inner[:, 1:] &= m[:, :-1]; inner[:, :-1] &= m[:, 1:]\n        if inner.sum() < 30:\n            continue\n        pts = backproject(c, inner)\n        P.append(pts); C.append(np.repeat(np.asarray(c["cam_pos"], float)[None], len(pts), 0))\n    if not P:\n        return None\n    P = np.concatenate(P); C = np.concatenate(C)\n    for _ in range(2):                                  # robust line\n        mu = np.median(P, 0)\n        a = np.linalg.svd(P - mu, full_matrices=False)[2][0]\n        dperp = np.linalg.norm((P - mu) - np.outer((P - mu) @ a, a), axis=1)\n        keep = dperp < 0.012\n        P, C = P[keep], C[keep]\n        if len(P) < 30:\n            return None\n    mu = P.mean(0)\n    a = np.linalg.svd(P - mu, full_matrices=False)[2][0]\n    b1 = unit(np.cross(a, EZ) if abs(a[2]) < 0.9 else np.cross(a, [1.0, 0, 0]))\n    b2 = np.cross(a, b1)\n    X = np.stack([(P - mu) @ b1, (P - mu) @ b2], 1)\n    vc = (C - P).mean(0)\n    vc2 = unit(np.array([vc @ b1, vc @ b2]))\n    cc = X.mean(0) - vc2 * RAD * 0.75\n    w = np.ones(len(X), bool)\n    for it in range(25):\n        d = X[w] - cc\n        r = np.linalg.norm(d, axis=1) + 1e-9\n        J = -d / r[:, None]\n        cc = cc + np.linalg.lstsq(J, -(r - RAD), rcond=None)[0]\n        if it == 12:\n            w = np.abs(np.linalg.norm(X - cc, axis=1) - RAD) < 0.0015\n    res = np.abs(np.linalg.norm(X[w] - cc, axis=1) - RAD)\n    ap = mu + cc[0] * b1 + cc[1] * b2\n    t = (P[w] - ap) @ a\n    t0, t1 = np.percentile(t, 0.3), np.percentile(t, 99.7)\n    return dict(a=a, ap=ap, p0=ap + t0 * a, p1=ap + t1 * a, ext=float(t1 - t0),\n                rms=float(np.sqrt((res ** 2).mean())), n=int(w.sum()))\n\n\ndef rod_ends(f, anchor_far_from=None):\n    """Both rod ends (length L) from a fit; if the visible extent is short, anchor on the visible end\n    farther from `anchor_far_from` (the other end is hidden by the fingers)."""\n    if f["ext"] > L - 0.004 or anchor_far_from is None:\n        c = (f["p0"] + f["p1"]) / 2\n        return c - f["a"] * L / 2, c + f["a"] * L / 2\n    d0 = np.linalg.norm(f["p0"] - anchor_far_from); d1 = np.linalg.norm(f["p1"] - anchor_far_from)\n    if d0 > d1:\n        return f["p0"], f["p0"] + f["a"] * L\n    return f["p1"] - f["a"] * L, f["p1"]\n\n\ndef heightmap_points(cams, center, radius=0.15):\n    pts = []\n    for n in ("global", "global2"):\n        c = cams[n]\n        sel = ~np.asarray(c["mask"], bool) & (c["depth"] > 0)\n        sel[::2, :] = False; sel[:, ::2] = False\n        P = backproject(c, sel)\n        P = P[np.linalg.norm(P[:, :2] - center[:2], axis=1) < radius]\n        pts.append(P)\n    return np.concatenate(pts)\n\n\nOBS0 = api.observe()\nGOAL_P = np.asarray(OBS0["goal_pos"], float)\nGOAL_R = quat_to_mat(np.asarray(OBS0["goal_quat"], float))\n_g0, _g1 = GOAL_P + GOAL_R @ E0, GOAL_P + GOAL_R @ E1\nGB, GT = (_g0, _g1) if _g0[2] <= _g1[2] else (_g1, _g0)   # goal bottom / top axis points\nprint("goal bottom", GB, "top", GT, "L", L, "RAD", RAD)\n\nCAMS0 = api.camera()\n# fixture top face height around the goal bore (ring just outside the bore radius)\n_hg = heightmap_points(CAMS0, GB, radius=0.03)\n_rg = np.linalg.norm(_hg[:, :2] - GB[:2], axis=1)\n_ring = _hg[(_rg > RAD + 0.0015) & (_rg < RAD + 0.006), 2]\nZ_TOP = float(np.percentile(_ring, 80)) if len(_ring) > 20 else GB[2] + 0.03\nZ_TOP = float(np.clip(Z_TOP, GB[2] + 0.002, GB[2] + L - 0.01))\nprint(f"fixture top around goal: {Z_TOP:.4f} (ring pts {len(_ring)}), bore depth {(Z_TOP - GB[2])*1000:.1f}mm")\nFIT0 = fit_rod(cams=CAMS0)\ntr = tracker()\nok = False\nev = "no mask fit"\nif FIT0 is not None:\n    R0E0, R0E1 = rod_ends(FIT0)\n    ROD_CTR0 = (R0E0 + R0E1) / 2\n    BOARD_Z = ROD_CTR0[2] - RAD\n    HM = heightmap_points(CAMS0, ROD_CTR0)\n    dtr = np.linalg.norm(((tr[0] + tr[1]) / 2 - ROD_CTR0)[:2]) * 1000 if tr else -1\n    ok = (abs(FIT0["a"][2]) < 0.3 and FIT0["rms"] < 0.0012 and FIT0["n"] > 300\n          and abs(FIT0["ext"] - L) < 0.006 and 0.0 < ROD_CTR0[2] < 0.04)\n    ev = (f"fit ctr={np.round(ROD_CTR0, 4).tolist()} axis={np.round(FIT0[\'a\'], 2).tolist()} ext={FIT0[\'ext\']*1000:.1f}mm "\n          f"rms={FIT0[\'rms\']*1000:.2f}mm n={FIT0[\'n\']} tracker-vs-fit xy={dtr:.1f}mm")\nprint(ev)\nstage_done(ok, ev)\n', True), ('grasp', 'stages/02_grasp.py', '# grasp: top-down pinch near one END (A) of the lying rod, then PIVOT the rod up against the board:\n# the far end B stays on the board while the (top-down, never rotating) hand moves on a circle around B\n# until the rod stands vertical under the fingers; lift -> the rod hangs vertically from the pinch.\n# Evidence: the fingertip pinch is a near-frictionless pivot about the closing axis (r09 s00 rod kept its\n# world orientation while the hand turned 90 deg; r07 s00 rod pinched 11 mm from its end hung vertical).\nTCP_ABOVE_BOARD = 0.0110   # start height of the fingertip feel-down\nTIP_REACH = 0.0089         # fingertips touch the board with the TCP ~8.8-9.2 mm above it (exp02, exp03)\nW_PRE = 0.03               # pre-grasp opening\nS_END = 0.010              # pinch this far from end A\nASCALE = np.asarray(api.constants()["action_scale"], float)\n\n\ndef servo(pos, R, n=20, grip=0.0, k=0.5, min_n=0, tol=0.0003):\n    """Cartesian servo of the TCP with the Jacobian, integrating its joint target (no steady-state\n    offset under gravity, r07). grip: action[7] (-1 close, +1 open, 0 keep)."""\n    o = api.observe()\n    q_t = np.asarray(o["joints"], float).copy()\n    for i in range(n):\n        o = api.observe()\n        e = np.asarray(pos, float) - np.asarray(o["tcp_pos"], float)\n        Rc = quat_to_mat(np.asarray(o["tcp_quat"], float))\n        w = 0.5 * sum(np.cross(Rc[:, j], R[:, j]) for j in range(3))\n        if i >= min_n and np.linalg.norm(e) < tol and np.linalg.norm(w) < 0.004:\n            break\n        en = np.linalg.norm(e)\n        if en > 0.01:\n            e = e / en * 0.01\n        J = np.asarray(o["tcp_jacobian"], float)\n        v = np.concatenate([k * e, k * w])\n        dq = J.T @ np.linalg.solve(J @ J.T + 1e-4 * np.eye(6), v)\n        q_m = np.asarray(o["joints"], float)\n        q_t = q_t + dq\n        q_t = q_m + np.clip(q_t - q_m, -0.6 * ASCALE, 0.6 * ASCALE)     # anti-windup\n        a = np.clip((q_t - q_m) / ASCALE, -1, 1)\n        api.step(np.concatenate([a, [grip]]))\n    return o\n\n\ndef in_tcp(T, p):\n    return T[:3, :3].T @ (p - T[:3, 3])\n\n\ndef clearance(g, R, zmin, zmax, half_x=0.014, half_y=0.012, gap=W_PRE / 2 + 0.010):\n    """Heightmap points (not the rod) inside the two finger footprints between zmin and zmax."""\n    y = R[:, 1]; x = R[:, 0]\n    n = 0\n    for sgn in (-1, 1):\n        d = HM - (g + sgn * y * gap)\n        n += int(((np.abs(d @ x) < half_x) & (np.abs(d @ y) < half_y) & (HM[:, 2] > zmin) & (HM[:, 2] < zmax)).sum())\n    return n\n\n\ndef top_down_R(a_h):\n    y_ax = unit(np.cross(EZ, a_h))\n    if y_ax @ np.array([0, -1.0, 0]) < 0:\n        y_ax = -y_ax\n    z_ax = -EZ\n    return np.column_stack([np.cross(y_ax, z_ax), y_ax, z_ax])\n\n\ndef choose_end(rE0, rE1):\n    a_h = rE1 - rE0; a_h[2] = 0; a_h = unit(a_h)\n    Rg = top_down_R(a_h)\n    best = None\n    for k, (eA, eB) in enumerate(((rE0, rE1), (rE1, rE0))):\n        u = eB - eA; u[2] = 0; u = unit(u)\n        g = eA + u * S_END\n        g = np.array([g[0], g[1], BOARD_Z + TCP_ABOVE_BOARD])\n        c0 = clearance(g, Rg, BOARD_Z + 0.003, g[2] + 0.06)\n        # hand above B at the end of the pivot: fingers span ~[B top - 12 mm, + 60 mm]\n        gB = np.array([eB[0], eB[1], BOARD_Z + L])\n        c1 = clearance(gB, Rg, BOARD_Z + L - S_END - 0.012, BOARD_Z + L + 0.06)\n        print(f"end cand A=end{k}: grasp {np.round(g, 4).tolist()} finger pts grasp {c0} / over B {c1}")\n        if best is None or c0 + c1 < best[0]:\n            best = (c0 + c1, k, eA, eB, u, g, Rg)\n    return best\n\n\ndef feel_down_and_close(G, R):\n    servo(G, R, n=30, k=0.5)\n    o = api.observe()\n    z_floor = BOARD_Z + TIP_REACH - 0.0015\n    zc = float(o["tcp_pos"][2])\n    touched = False\n    for _ in range(40):\n        o = api.observe()\n        if float(o["tcp_wrench_ext"][2]) > 3.0:\n            touched = True\n            break\n        zc = max(zc - 0.0003, z_floor)\n        servo(np.array([G[0], G[1], zc]), R, n=1, k=1.0)\n        if zc <= z_floor:\n            break\n    o = api.observe()\n    g_hold = np.array([G[0], G[1], float(o["tcp_pos"][2]) + 0.0004])\n    print(f"  board contact {touched} at tcp z {o[\'tcp_pos\'][2]:.4f} (board {BOARD_Z:.4f}); hold z {g_hold[2]:.4f}")\n    servo(g_hold, R, n=6, k=0.5, min_n=6)\n    servo(g_hold, R, n=20, grip=-1.0, k=0.4, min_n=20)      # close while holding the pose\n    o = api.observe()\n    print("  closed: width", round(float(o["gripper_width"]), 4), "F", np.round(o["tcp_wrench_ext"][:3], 1))\n    return g_hold\n\n\nok = False\nev = "not attempted"\nrE0, rE1 = R0E0, R0E1\nfor attempt in range(2):\n    _, K_SEL, eA, eB, U_AB, G_PT, R_GRASP = choose_end(rE0, rE1)\n    Q_GRASP = mat_to_quat(R_GRASP)\n    print(f"attempt {attempt}: hold end{K_SEL} at {np.round(G_PT, 4).tolist()}")\n    api.move_to(G_PT + EZ * 0.08, Q_GRASP, timeout_s=3.0)\n    api.set_gripper(width=W_PRE, hold_s=0.3)\n    api.move_to(G_PT + EZ * 0.015, Q_GRASP, timeout_s=2.0)\n    g_hold = feel_down_and_close(G_PT, R_GRASP)\n\n    # pivot about B\'s lower rim, keeping |pinch - B| constant (0.5 mm short to keep B pressed on the board)\n    P0 = eA + U_AB * S_END                 # pinch point on the rod axis\n    P0[2] = (eA[2] + eB[2]) / 2\n    off = g_hold - P0                      # TCP relative to the pinch (hand orientation is fixed)\n    Bax = eB.copy(); Bax[2] = P0[2]\n    Q = Bax - RAD * EZ\n    d = np.linalg.norm((P0 - Bax)[:2]) - 0.0005\n    for phi in np.radians(np.linspace(5, 92, 18)):\n        Bp = Q + RAD * (U_AB * np.sin(phi) + EZ * np.cos(phi))\n        P = Bp + d * (-U_AB * np.cos(phi) + EZ * np.sin(phi))\n        servo(P + off, R_GRASP, n=5, k=0.6)\n    o = api.observe()\n    print("  after pivot: tcp", np.round(o["tcp_pos"], 4), "F", np.round(o["tcp_wrench_ext"][:3], 1),\n          "width", round(float(o["gripper_width"]), 4))\n    # lift slowly; the rod hangs from the pinch\n    T = tcp_T()\n    servo(T[:3, 3] + EZ * 0.06, R_GRASP, n=40, k=0.25)\n    api.wait(0.4)\n\n    f = fit_rod()\n    T = tcp_T()\n    if f is None:\n        ev = f"attempt {attempt}: no mask fit after the pivot/lift"\n    else:\n        lo, hi = (f["p0"], f["p1"]) if f["p0"][2] < f["p1"][2] else (f["p1"], f["p0"])\n        tilt = np.degrees(np.arccos(min(1.0, abs(f["a"][2]))))\n        top_d = np.linalg.norm(hi[:2] - T[:3, 3][:2])\n        ok = tilt < 15 and lo[2] > BOARD_Z + 0.02 and top_d < 0.02 and f["n"] > 150\n        ev = (f"attempt {attempt}: rod hanging, tilt {tilt:.1f}deg, bottom z {lo[2]:.4f} (board {BOARD_Z:.4f}), "\n              f"top {top_d*1000:.0f}mm from TCP axis, ext {f[\'ext\']*1000:.0f}mm rms {f[\'rms\']*1000:.2f}")\n    print(ev)\n    if ok:\n        break\n    # failed: open, back off, re-locate the rod and retry\n    servo(np.asarray(api.observe()["tcp_pos"], float), R_GRASP, n=10, grip=1.0, min_n=10)\n    api.move_to(np.asarray(api.observe()["tcp_pos"], float) + EZ * 0.08, Q_GRASP, timeout_s=2.0)\n    f = fit_rod()\n    if f is None or abs(f["a"][2]) > 0.3 or abs(f["ext"] - L) > 0.006:\n        print("  re-locate failed")\n        break\n    rE0, rE1 = rod_ends(f)\n    BOARD_Z = ((rE0 + rE1) / 2)[2] - RAD\n    print("  re-located rod ctr", np.round((rE0 + rE1) / 2, 4))\nstage_done(ok, ev)\n', True), ('insert', 'stages/03_insert.py', '# insert: the rod hangs vertically from a top-down pinch. Carry it (orientation unchanged) over the bore,\n# let it settle, align its measured bottom over the bore axis by translation, step down into the bore\n# (back out + re-align if blocked above the fixture top), release near the bottom, lift; verify.\nR_TD = tcp_T()[:3, :3]\nQ_TD = mat_to_quat(R_TD)\n\n\ndef measure_hanging(settle=True):\n    """Rod bottom/top from the camera fit (waits until two fits agree, the rod may swing)."""\n    prev = None\n    for _ in range(4 if settle else 1):\n        api.wait(0.2)\n        f = fit_rod()\n        if f is None:\n            return None\n        T = tcp_T()\n        lo = f["p0"] if f["p0"][2] < f["p1"][2] else f["p1"]\n        m0, m1 = rod_ends(f, anchor_far_from=lo + EZ * 1.0)\n        mb, mc = (m0, m1) if m0[2] < m1[2] else (m1, m0)\n        if np.linalg.norm((mb + mc) / 2 - T[:3, 3]) > 0.07:\n            return None\n        cur = dict(b=mb, c=mc, a=unit(mb - mc), T=T, f=f)\n        if prev is not None and np.linalg.norm(cur["b"] - prev["b"]) < 0.0004:\n            return cur\n        prev = cur\n    return prev\n\n\nm = measure_hanging()\nif m is None:\n    stage_done(False, "rod not seen hanging in the hand")\noff_b = m["b"] - m["T"][:3, 3]                       # rod bottom relative to the TCP (world frame)\nprint("rod bottom rel. TCP (mm)", np.round(off_b * 1000, 1), "tilt", round(np.degrees(np.arccos(min(1, -m[\'a\'][2]))), 1))\nZ_PRE = Z_TOP + 0.012\np_cmd = np.array([GB[0], GB[1], Z_PRE]) - off_b\nT = tcp_T()\napi.move_to(np.array([T[0, 3], T[1, 3], max(T[2, 3], p_cmd[2] + 0.04)]), Q_TD, timeout_s=2.0, gain=0.4)\napi.move_to(p_cmd + EZ * 0.04, Q_TD, timeout_s=4.0, gain=0.3)\nservo(p_cmd, R_TD, n=40, k=0.3)\n\n\ndef align(z_bottom, iters=5, tag=""):\n    """Translate the TCP so the measured rod bottom sits at (goal xy, z_bottom)."""\n    global p_cmd\n    m = None\n    for it in range(iters):\n        m = measure_hanging()\n        if m is None:\n            print(f"align{tag} {it}: rod not seen"); return None\n        err = np.array([GB[0], GB[1], z_bottom]) - m["b"]\n        tilt = np.degrees(np.arccos(np.clip(-m["a"][2], -1, 1)))\n        print(f"align{tag} {it}: bottom {np.round(m[\'b\'], 4)} tilt {tilt:.2f}deg xy err {np.round(err[:2]*1000, 2)}mm "\n              f"z err {err[2]*1000:.1f}mm ext {m[\'f\'][\'ext\']*1000:.0f} rms {m[\'f\'][\'rms\']*1000:.2f}")\n        if np.linalg.norm(err[:2]) < 0.0004 and abs(err[2]) < 0.0015:\n            return m\n        if np.linalg.norm(err) > 0.03:\n            print("align: error too large, not trusted"); return None\n        p_cmd = np.asarray(m["T"][:3, 3], float) + err\n        servo(p_cmd, R_TD, n=30, k=0.4)\n    return measure_hanging()\n\n\nm = align(Z_PRE)\nif m is None:\n    stage_done(False, "alignment over the bore failed")\n\n# step down; blocked = the TCP stays short of its target\nZ_REL = GB[2] + 0.003\nz_targets = [Z_TOP + 0.004] + list(np.arange(Z_TOP - 0.002, Z_REL - 1e-4, -0.003)) + [Z_REL]\nb_now = m["b"].copy()\nretries = 0\ni = 0\nwhile i < len(z_targets):\n    zb = z_targets[i]\n    T = tcp_T()\n    tgt = T[:3, 3] + EZ * (zb - b_now[2])\n    servo(tgt, R_TD, n=20, k=0.4)\n    o = api.observe()\n    short = o["tcp_pos"][2] - tgt[2]\n    F = np.asarray(o["tcp_wrench_ext"], float)\n    print(f"step bottom->{zb:.4f}: tcp short by {short*1000:.1f}mm F={np.round(F[:3], 1)}")\n    b_now = b_now + EZ * (zb - b_now[2]) + EZ * short\n    if short > 0.0015 and zb > Z_TOP - 0.006:\n        # tip on the fixture face: back out, re-align, restart\n        retries += 1\n        if retries > 2:\n            break\n        T = tcp_T()\n        servo(T[:3, 3] + EZ * (Z_TOP + 0.008 - b_now[2]), R_TD, n=25, k=0.4)\n        mm = align(Z_TOP + 0.008, iters=3, tag="R")\n        if mm is None:\n            break\n        b_now = mm["b"].copy()\n        i = 0\n        continue\n    if short > 0.0015:\n        # inside the bore but stuck (pinch slides / bottom reached): stop pushing\n        print("stuck inside the bore -> release here")\n        break\n    i += 1\nprint("release at rod bottom ~", round(float(b_now[2]), 4))\nT = tcp_T()\nservo(T[:3, 3], R_TD, n=12, grip=1.0, k=0.4, min_n=12)      # open while holding the pose\nservo(T[:3, 3] + EZ * 0.08, R_TD, n=30, k=0.4)\napi.wait(0.3)\n\nf = fit_rod()\nok = False\nev = "no mask fit"\nif f is not None:\n    top = f["p1"] if f["p1"][2] > f["p0"][2] else f["p0"]\n    a = unit(f["p1"] - f["p0"])\n    lam = (GT[2] - top[2]) / a[2] if abs(a[2]) > 0.5 else 0.0\n    xy = np.linalg.norm((top + lam * a - GT)[:2])\n    dz = top[2] - GT[2]\n    ok = abs(a[2]) > 0.98 and xy < 0.002 and abs(dz) < 0.0025\n    ev = f"mask fit: axis z {abs(a[2]):.3f}, top z {top[2]:.4f} vs goal {GT[2]:.4f} ({dz*1000:+.1f}mm), axis xy off {xy*1000:.1f}mm"\nprint(ev)\nstage_done(ok, ev)\n', True)]   # (name, file, source, strict): a strict stage stops the policy on FAIL


class StageFailed(Exception):
    pass


def policy(api):
    ns = dict(api=api, np=np)
    cur = [None, True]

    def stage_done(ok, evidence=""):
        api._rec("stage_done", stage=cur[0], ok=bool(ok), evidence=str(evidence)[:200])
        print(f"[STAGE {cur[0]}] {'PASS' if ok else 'FAIL'} {evidence}", flush=True)
        if not ok and cur[1] and getattr(api, "strict_stages", True):
            raise StageFailed(cur[0])

    ns["stage_done"] = stage_done
    try:
        for name, fname, src, strict in STAGES:
            cur[0], cur[1] = name, strict
            print(f"=== {name} ({fname}) ===", flush=True)
            try:
                exec(compile(src, fname, "exec"), ns)
            except (StageFailed, _api.EpisodeOver, _api.LevelError):
                raise
            except Exception as e:
                traceback.print_exc()
                api._rec("stage_done", stage=name, ok=False, evidence=f"exception {type(e).__name__}: {e}"[:200])
                print(f"[STAGE {name}] FAIL exception {type(e).__name__}: {e}", flush=True)
                raise StageFailed(name)
    except StageFailed:
        return                        # the episode goes on without the policy
